export class HardSkill {
  constructor(skill, level) {
    this._skill = skill;
    this._level = level;
  }
  get skill() {
    return this._skill;
  }
  set skill(skill) {
    this._skill = skill;
  }
  get level() {
    return this._level;
  }
  set level(level) {
    this._level = level;
  }
}
